import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../../redux/store';
import { selectAuth } from '../../../redux/authSlice';
import { useHobitMutateDeleteApi, useHobitQueryGetApi } from '../../../hooks/hobitAdmin';
import { BulkDeleteEmailRequest, BulkDeleteEmailResponse, GetAllEmailsRequest, GetAllEmailsResponse } from '../../../types/email';

import { appAlert } from '../../ui/Dialog';
import Icon from '../../ui/Icon';
import { useEmbedded } from '../embedded';
const BulkDeleteEmail: React.FC = () => {
  const emb = useEmbedded(); // 관리 탭 안에 끼워 넣었으면 상자·큰 제목 없이
  const { user_id } = useSelector((state: RootState) => selectAuth(state));
  const [email, setEmail] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [showConfirmPopup, setShowConfirmPopup] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [emailList, setEmailList] = useState<string[]>([]);

  const bulkDeleteEmailApi = useHobitMutateDeleteApi<BulkDeleteEmailRequest, BulkDeleteEmailResponse>(
    'emails/bulk-delete'
  );

  const getAllEmailsApi = useHobitQueryGetApi<GetAllEmailsRequest, GetAllEmailsResponse>('emails');

  useEffect(() => {
    if (getAllEmailsApi.data?.payload?.statusCode === 200) {
      setEmailList(getAllEmailsApi.data.payload.data.emails);
    }
  }, [getAllEmailsApi.data]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!email) {
      appAlert('삭제할 이메일을 입력해주세요.');
      return;
    }

    // 이메일 형식 검증
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      appAlert('올바른 이메일 형식을 입력해주세요.');
      return;
    }

    setShowConfirmPopup(true);
  };

  const handleConfirmDelete = async () => {
    setIsDeleting(true);
    setShowConfirmPopup(false);

    try {
      const response = await bulkDeleteEmailApi({
        body: {
          email: email,
          user_id: Number(user_id),
        },
      });

      if (response.payload?.statusCode === 200) {
        const { updated_faqs } = response.payload.data;
        appAlert(
          `이메일이 성공적으로 삭제되었습니다!\n\n` +
          `삭제된 FAQ: ${updated_faqs}건`
        );
        setEmail('');
        // 이메일 목록 새로고침
        getAllEmailsApi.refetch();
      } else {
        appAlert('이메일 삭제 중 오류가 발생했습니다. 다시 시도해주세요.');
      }
    } catch (error) {
      console.error('이메일 삭제 오류:', error);
      appAlert('이메일 삭제 중 오류가 발생했습니다.');
    } finally {
      setIsDeleting(false);
    }
  };

  const handleEmailSelect = (selectedEmail: string) => {
    setEmail(selectedEmail);
    setShowDropdown(false);
  };

  const filteredEmails = emailList.filter(e => 
    e.toLowerCase().includes(email.toLowerCase())
  );

  return (
    <div className={emb ? '' : 'flex justify-center items-center py-6 sm:min-h-[calc(100vh-4.5rem)] sm:py-10'}>
      <div className={emb ? 'w-full' : 'bg-surface p-5 sm:p-8 rounded-xl shadow-lg w-full max-w-md'}>
        {!emb && (<h2 className="text-xl sm:text-2xl font-bold mb-6 text-center text-ink">
          이메일 전체 삭제
        </h2>)}
        <p className={emb ? 'mb-4 text-sm text-ink-3' : 'text-sm text-ink-2 mb-6 text-center'}>
          모든 FAQ의 답변에서 특정 이메일을 일괄 삭제합니다.
        </p>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="relative">
            <label className="block text-sm font-medium text-ink mb-2">
              삭제할 이메일
            </label>
            <input
              type="text"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                setShowDropdown(true);
              }}
              onFocus={() => setShowDropdown(true)}
              onBlur={() => setTimeout(() => setShowDropdown(false), 200)}
              placeholder="example@korea.ac.kr"
              className="w-full px-4 py-2 border border-line rounded-xl focus:ring-2 focus:ring-danger/40 focus:border-transparent"
              disabled={isDeleting}
              autoComplete="off"
            />
            {showDropdown && filteredEmails.length > 0 && (
              <div className="absolute z-10 w-full mt-1 bg-surface border border-line rounded-xl shadow-lg max-h-60 overflow-y-auto">
                {filteredEmails.map((e, index) => (
                  <button
                    key={index}
                    type="button"
                    onClick={() => handleEmailSelect(e)}
                    className="w-full text-left px-4 py-2 hover:bg-card transition-colors"
                  >
                    {e}
                  </button>
                ))}
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={isDeleting}
            className={`w-full py-3 px-4 rounded-xl font-semibold text-white transition-[background-color,transform] duration-300 ${
              isDeleting
                ? 'bg-card-3 cursor-not-allowed'
                : 'bg-danger hover:bg-danger/90 transform hover:scale-105'
            }`}
          >
            {isDeleting ? '삭제 중...' : '이메일 삭제'}
          </button>
        </form>

        <div className="mt-6 p-4 bg-danger-soft border border-danger/40 rounded-xl">
          <p className="flex items-start gap-2 text-sm leading-relaxed text-danger">
            <Icon name="alert" className="mt-[3px] h-4 w-4 shrink-0" />
            <span><strong>주의:</strong> 이 작업은 되돌릴 수 없습니다. 해당 이메일이 모든 FAQ에서 삭제됩니다.</span>
          </p>
        </div>
      </div>

      {/* 확인 팝업 */}
      {showConfirmPopup && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-[440px]">
            <h3 className="text-xl font-bold mb-4 text-ink">이메일 삭제 확인</h3>
            <p className="text-ink-2 mb-2">
              모든 데이터베이스에서 다음 이메일을 삭제하시겠습니까?
            </p>
            <div className="bg-card p-4 rounded-xl my-4">
              <p className="text-sm">
                <span className="font-semibold">삭제할 이메일:</span>{' '}
                <span className="text-danger">{email}</span>
              </p>
            </div>
            <p className="flex items-start gap-2 text-sm text-danger mb-4">
              <Icon name="alert" className="mt-[3px] h-4 w-4 shrink-0" />
              <span>이 작업은 되돌릴 수 없습니다.</span>
            </p>
            <div className="flex space-x-3">
              <button
                onClick={() => setShowConfirmPopup(false)}
                className="flex-1 px-4 py-2 bg-card-2 text-ink rounded-xl hover:bg-card-3 transition-colors"
              >
                취소
              </button>
              <button
                onClick={handleConfirmDelete}
                className="flex-1 px-4 py-2 bg-danger text-white rounded-xl hover:bg-danger/90 transition-colors"
              >
                확인
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BulkDeleteEmail;
